   "enunciado": "Es referido desde Huamachuco, un paciente varón, de 36 horas de edad, nacido a término, con un peso de 2,800 gr, ha presentado vómitos desde las 12 horas de vida, al inicio lácteos actualmente biliosos, luce deshidratado y al examen del abdomen esta distendido, los ruidos intestinales están aumentados de intensidad y frecuencia e impresiona algún grado de dolor a la palpación. La madre nos refiere que realizó deposiciones escasas, y las describe como tapones grises de moco. La madre no refiere antecedentes de enfermedades en su familia ni en la de su esposo, ambos son mestizos y se dedican a la agricultura, en los controles prenatales no le dijeron que había alteraciones, tiene dos controles ecográficos en el primer y tercer trimestre normales. Usted sospecha de una atresia intestinal (yeyuno-ileal) por lo que solicita una radiografía simple de abdomen, ¿Qué hallazgos radiológicos confirmarían su hipótesis diagnostica?",
